//! Read-operation sequences compared with `/usr/bin/php`
//! (generated by `tests/data/gen_readops.php`; keep the lists in sync).

use php_streams::file;
use php_streams::open;
use php_streams::stream::Stream;

fn contents() -> Vec<Vec<u8>> {
    let mut big = vec![b'x'; 9000];
    big.push(b'\n');
    big.extend(std::iter::repeat_n(b'y', 100));
    big.extend_from_slice(b"\nend");
    vec![
        b"line1\nline2\nline3".to_vec(),
        b"a\n\nb\r\nc\n".to_vec(),
        big,
        Vec::new(),
        b"no newline at all".to_vec(),
        b"\r\r\n\n".to_vec(),
    ]
}

const SCRIPTS: &[&str] = &[
    "fgets;fgets;fgets;fgets;feof",
    "fgets 3;fgets 3;fgets 2;fgets 1;ftell;feof",
    "fread 4;fread 100;feof;fread 1;feof",
    "fgetc;fgetc;ftell;fseek 0 0;fgets;ftell",
    "sgl 100 \\n;sgl 3 ;sgl 100 zz;sgl 100 \\n;feof",
    "fseek 2 1;ftell;fgets;fseek -3 2;fread 10;feof;fseek 1 0;fgetc",
    "fread 8192;fread 8192;fgets;feof;ftell",
    "sgc -1 3;sgc 2 0;sgc -1 -1",
    "fgets 9002;fgets;fgets",
];

fn hex(b: &[u8]) -> String {
    use std::fmt::Write;
    b.iter().fold(String::new(), |mut s, c| {
        let _ = write!(s, "{c:02x}");
        s
    })
}

fn enc_bytes(v: Option<Vec<u8>>) -> String {
    v.map_or_else(|| "F".to_string(), |b| format!("S{}", hex(&b)))
}

fn enc_bool(b: bool) -> String {
    if b { "T" } else { "F" }.to_string()
}

fn open_kind(kind: &str, path: &[u8], content: &[u8]) -> Stream {
    match kind {
        "memory" | "temp" => {
            let url: &[u8] = if kind == "memory" {
                b"php://memory"
            } else {
                b"php://temp/maxmemory:16"
            };
            let mut s = open::fopen(url, "w+", false, None).unwrap();
            s.write(content).ok();
            s.rewind();
            s
        }
        _ => {
            let mut s = open::fopen(path, "r", false, None).unwrap();
            if kind == "filtered" {
                file::stream_filter_attach(&mut s, "string.rot13", 1, None, true).unwrap();
            } else if kind == "chunk3" {
                file::stream_set_chunk_size(&mut s, 3).unwrap();
            }
            s
        }
    }
}

fn run(s: &mut Stream, script: &str) -> Vec<String> {
    let mut out = Vec::new();
    for cmd in script.split(';') {
        let p: Vec<&str> = cmd.splitn(3, ' ').collect();
        let n = |i: usize| p.get(i).map_or(0, |v| v.parse::<i64>().unwrap());
        let r = match p[0] {
            "fgets" => enc_bytes(file::fgets(s, p.get(1).map(|_| n(1))).unwrap()),
            "fread" => enc_bytes(file::fread(s, n(1)).unwrap()),
            "fgetc" => enc_bytes(s.getc().map(|c| vec![c])),
            "feof" => enc_bool(s.eof()),
            "ftell" => file::ftell(s).map_or("F".into(), |v| format!("I{v}")),
            "fseek" => format!("I{}", file::fseek(s, n(1), n(2))),
            "sgl" => {
                let delim = p.get(2).copied().unwrap_or("").replace("\\n", "\n");
                enc_bytes(file::stream_get_line(s, n(1), delim.as_bytes()).unwrap())
            }
            "sgc" => {
                let max = if n(1) < 0 { None } else { Some(n(1)) };
                enc_bytes(file::stream_get_contents(s, max, n(2)).unwrap())
            }
            other => panic!("unknown op {other}"),
        };
        out.push(r);
    }
    out
}

#[test]
fn read_ops_match_php() {
    let dir = std::env::temp_dir().join(format!("php-streams-readops-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("f");
    let pathb = path.to_str().unwrap().as_bytes().to_vec();
    let contents = contents();
    let oracle = include_str!("data/readops_oracle.txt");
    let mut failures = Vec::new();
    let mut n = 0;
    for line in oracle.lines() {
        let f: Vec<&str> = line.split('\t').collect();
        let ci: usize = f[0].parse().unwrap();
        let si: usize = f[2].parse().unwrap();
        std::fs::write(&path, &contents[ci]).unwrap();
        let mut s = open_kind(f[1], &pathb, &contents[ci]);
        let got = run(&mut s, SCRIPTS[si]).join(",");
        s.close();
        if got != f[3] {
            failures.push(format!(
                "content {ci} kind {} script {:?}\n  php:  {}\n  ours: {got}",
                f[1], SCRIPTS[si], f[3]
            ));
        }
        n += 1;
    }
    let _ = std::fs::remove_dir_all(&dir);
    assert_eq!(n, 270);
    assert!(
        failures.is_empty(),
        "{} mismatches:\n{}",
        failures.len(),
        failures.join("\n")
    );
}
